CustomField.formula:
OR(
/* ---------- NEW STUDENTS ---------- */ AND( CONTAINS(TEXT(LearnerAccount.Student_Type__c),"New"), NOT(ISBLANK(TEXT( EnrollmentStatus ))), OR( CONTAINS(TEXT(Birth_Certificate__c),"Uploaded"), CONTAINS(TEXT(Proof_of_NYS_Residency_1__c),"Uploaded"), CONTAINS(TEXT(Immunization_Records__c),"Uploaded"), CONTAINS(TEXT(Proof_of_NYS_Residency_2__c),"Uploaded"), CONTAINS(TEXT(Home_Language_Questionnaire__c),"Uploaded"), CONTAINS(TEXT(Physical_Upload__c),"Uploaded"), CONTAINS(TEXT(Activities_Field_Trip_Consent_Form__c),"Completed"), CONTAINS(TEXT(Parent_Contract__c),"Completed"), CONTAINS(TEXT(Consent_to_Release_Student_Records__c),"Completed"), CONTAINS(TEXT(Student_Info_Contact_Form__c),"Completed"), CONTAINS(TEXT(Computer_Tablet_Use_Consent_Form__c),"Completed"), CONTAINS(TEXT(Uploaded_IEP__c),"but"), CONTAINS(TEXT(Laptop_Tablet_Agreement__c),"Completed"), CONTAINS(TEXT(MAF_Upload__c),"but"), CONTAINS(TEXT(Ethnic_Identification_Form__c),"Completed"), CONTAINS(TEXT(Housing_Questionnaire__c),"Completed"), CONTAINS(TEXT(FERPA_Directory_Info_Notice__c),"Completed"), CONTAINS(TEXT(Media_Photo_Release__c),"Completed"), CONTAINS(TEXT(TELA_Fee_Form__c),"Completed"), CONTAINS(TEXT(Overnight_Trip_Form__c),"Completed") ) ),
/* ---------- RETURNING STUDENTS ---------- */ AND( CONTAINS(TEXT(LearnerAccount.Student_Type__c),"Returning"), NOT(ISBLANK(TEXT( EnrollmentStatus ))), OR( CONTAINS(TEXT(Parent_Contract__c),"Completed"), CONTAINS(TEXT(Student_Info_Contact_Form__c),"Completed"), CONTAINS(TEXT(Housing_Questionnaire__c),"Completed"), CONTAINS(TEXT(Overnight_Trip_Form__c),"Completed"), CONTAINS(TEXT(FERPA_Directory_Info_Notice__c),"Completed") ) )
)
